                if(document.getElementById('liuwanyi-dependency')) document.getElementById('liuwanyi-dependency').innerText = 'N/A';
                if(document.getElementById('liuwanyi-stage-header')) document.getElementById('liuwanyi-stage-header').innerText = '(数据缺失)';
