                const stageHeaderLQL = document.getElementById('liuqinglu-stage-header');
                if (stageHeaderLQL) stageHeaderLQL.innerText = `(${stageTextLQL})`;

                updateProgressBar('liuqinglu-adoration-bar', 'liuqinglu-adoration', adorationValueLQL, 0, 100, 'var(--accent-sister)');
                updateProgressBar('liuqinglu-tolerance-bar', 'liuqinglu-tolerance', SafeGetValue(characterData, `${lqlKey}.情感包容度`), 0, 100, 'var(--accent-sister)');
            } else {
                 if(document.getElementById('liuqinglu-adoration')) document.getElementById('liuqinglu-adoration').innerText = 'N/A';
                 if(document.getElementById('liuqinglu-stage-header')) document.getElementById('liuqinglu-stage-header').innerText = '(数据缺失)';
                 if(document.getElementById('liuqinglu-adoration-bar')) document.getElementById('liuqinglu-adoration-bar').style.width = '0%';
                 if(document.getElementById('liuqinglu-tolerance')) document.getElementById('liuqinglu-tolerance').innerText = 'N/A';
                 if(document.getElementById('liuqinglu-tolerance-bar')) document.getElementById('liuqinglu-tolerance-bar').style.width = '0%';
            }

        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
            console.error("Error in initDisplay:", error);
