        const valueMainDisplay = document.getElementById(valueMainId);

        if (!valueMainDisplay) {
            console.warn(`Element with ID ${valueMainId} not found.`);
            return;
        }

        let fullDisplayString = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
        let numericValue = min;

        const valueMatch = String(fullDisplayString).match(/(-?\d+(\.\d+)?)(?=[^\d.]*$|->)/);
         if (valueMatch) {
            numericValue = parseFloat(valueMatch[1]);
            const parts = String(fullDisplayString).split('->');
            valueMainDisplay.innerText = parts.length > 1 ? parts[1].trim() : parts[0].trim();
         } else if (!isNaN(parseFloat(fullDisplayString))) {
             numericValue = parseFloat(fullDisplayString);
             valueMainDisplay.innerText = fullDisplayString;
         } else {
             if (Array.isArray(rawValueFromCharacterData) && typeof rawValueFromCharacterData[0] === 'number') {
                 numericValue = rawValueFromCharacterData[0];
                 valueMainDisplay.innerText = String(numericValue);
             } else if (typeof rawValueFromCharacterData === 'number' || typeof rawValueFromCharacterData === 'string' || typeof rawValueFromCharacterData === 'boolean') {
                 valueMainDisplay.innerText = String(rawValueFromCharacterData);
             } else {
                 valueMainDisplay.innerText = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
             }
         }

        if (progressBar) {
            numericValue = Math.max(min, Math.min(max, numericValue));
            const range = max - min;
            const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
            if(color) { // Apply color only if specified
                progressBar.style.backgroundColor = color;
            }
        } else {
            console.warn(`Progress bar with ID ${barId} not found.`);
        }
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (messages empty)</p>";
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;
            if (!characterData) {
                 document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (characterData missing)</p>";
                 return;
            }

            //柳婉仪数据
            const lwyKey = "柳婉仪";
            if (characterData.hasOwnProperty(lwyKey)) {
                const dependencyValueLWY = SafeGetValue(characterData, `${lwyKey}.对{{user}}的依赖度`);
                const stageTextLWY = GetDependencyStageTextLWY(dependencyValueLWY);
                const stageHeaderLWY = document.getElementById('liuwanyi-stage-header');
                if (stageHeaderLWY) stageHeaderLWY.innerText = `(${stageTextLWY})`;

                updateProgressBar('liuwanyi-dependency-bar', 'liuwanyi-dependency', dependencyValueLWY, 0, 100, 'var(--accent-empress)');
                updateProgressBar('liuwanyi-tolerance-bar', 'liuwanyi-tolerance', SafeGetValue(characterData, `${lwyKey}.情感包容度`), 0, 100, 'var(--accent-empress)');
            } else {
                if(document.getElementById('liuwanyi-dependency')) document.getElementById('liuwanyi-dependency').innerText = 'N/A';
                if(document.getElementById('liuwanyi-stage-header')) document.getElementById('liuwanyi-stage-header').innerText = '(数据缺失)';
                if(document.getElementById('liuwanyi-dependency-bar')) document.getElementById('liuwanyi-dependency-bar').style.width = '0%';
                if(document.getElementById('liuwanyi-tolerance')) document.getElementById('liuwanyi-tolerance').innerText = 'N/A';
                if(document.getElementById('liuwanyi-tolerance-bar')) document.getElementById('liuwanyi-tolerance-bar').style.width = '0%';
            }

            //柳清露数据
            const lqlKey = "柳清露";
            if (characterData.hasOwnProperty(lqlKey)) {
                const adorationValueLQL = SafeGetValue(characterData, `${lqlKey}.对{{user}}的爱慕值`);
                const stageTextLQL = GetAdorationStageTextLQL(adorationValueLQL);
                const stageHeaderLQL = document.getElementById('liuqinglu-stage-header');
                if (stageHeaderLQL) stageHeaderLQL.innerText = `(${stageTextLQL})`;

                updateProgressBar('liuqinglu-adoration-bar', 'liuqinglu-adoration', adorationValueLQL, 0, 100, 'var(--accent-sister)');
                updateProgressBar('liuqinglu-tolerance-bar', 'liuqinglu-tolerance', SafeGetValue(characterData, `${lqlKey}.情感包容度`), 0, 100, 'var(--accent-sister)');
            } else {
                 if(document.getElementById('liuqinglu-adoration')) document.getElementById('liuqinglu-adoration').innerText = 'N/A';
                 if(document.getElementById('liuqinglu-stage-header')) document.getElementById('liuqinglu-stage-header').innerText = '(数据缺失)';
                 if(document.getElementById('liuqinglu-adoration-bar')) document.getElementById('liuqinglu-adoration-bar').style.width = '0%';
                 if(document.getElementById('liuqinglu-tolerance')) document.getElementById('liuqinglu-tolerance').innerText = 'N/A';
                 if(document.getElementById('liuqinglu-tolerance-bar')) document.getElementById('liuqinglu-tolerance-bar').style.width = '0%';
            }

        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
            console.error("Error in initDisplay:", error);
        }
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        const isExpanded = content.classList.contains('expanded'); // Check before toggling
        content.classList.toggle('expanded');
        element.classList.toggle('expanded-header', !isExpanded); // Apply based on new state
        arrow.innerText = !isExpanded ? '▲' : '▼';
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
</body>
